INSERT INTO feature VALUES('std-module-map','modules','The standard library''s module map','packages','implemented','ordinary',NULL,'`library/std/README.md` maps each module of `std`: what it holds, the corpus sources it absorbs, the host seam it stands on with the `cap-std` type it mirrors, and whether it is landed, reserved or declined; host access is by capability, the ambient authority entering as `main`''s parameter. Modules are lowercase and follow Rust''s hierarchy, `std.io` beside `std.fs`, `std.net`, `std.process`, `std.env`, `std.time` and `std.rand`, and theoretical mathematics stands under `std.math`.',NULL,'library/std/README.md','corpus/model/projects/hello/package.gandr','#628');
